using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor.SceneManagement;using UnityEngine.SceneManagement;using Newtonsoft.Json;
public static class C02RefineWalk {
 public static object Run(){var s=SceneManager.GetActiveScene();if(s.isDirty||Application.isPlaying)throw new Exception("Saved edit scene required");var origin=new Vector3(-22,-82,18);var doors=new[]{new Vector3(1.503721f,0,-6.014883f),new Vector3(-5.644272f,0,2.565578f),new Vector3(6.19143f,0,.325865f)};var player=s.GetRootGameObjects().Single(g=>g.name.StartsWith("Player"));var cc=player.GetComponent<CharacterController>();var old=player.transform.position;bool enabled=cc.enabled;var results=new List<object>();
 try{for(int a=0;a<3;a++)for(int b=0;b<3;b++){if(a==b)continue;var start=origin+doors[a]+doors[a].normalized*1.2f;var end=origin+doors[b]+doors[b].normalized*1.2f;cc.enabled=false;player.transform.position=start+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();int steps=0;float remaining=0;bool okay=true;foreach(var dest in new[]{origin,end}){for(int i=0;i<1200;i++){var d=dest-player.transform.position;d.y=0;remaining=d.magnitude;if(remaining<.06f)break;cc.Move(d.normalized*Mathf.Min(.10f,remaining)+Vector3.down*.08f);steps++;}if(remaining>.10f){okay=false;break;}}results.Add(new{from=a,to=b,steps,remaining,passed=okay});}
 var extraStart=origin+doors[2];var extraEnd=origin+new Vector3(32.807187f,0,1.726694f);cc.enabled=false;player.transform.position=extraStart+Vector3.up*(cc.height*.5f-cc.center.y+.04f);cc.enabled=true;Physics.SyncTransforms();int extraSteps=0;float extraRemaining=0;for(int i=0;i<1400;i++){var d=extraEnd-player.transform.position;d.y=0;extraRemaining=d.magnitude;if(extraRemaining<.06f)break;cc.Move(d.normalized*Mathf.Min(.10f,extraRemaining)+Vector3.down*.08f);extraSteps++;}results.Add(new{from=2,to=3,steps=extraSteps,remaining=extraRemaining,passed=extraRemaining<.10f});
 }finally{cc.enabled=false;player.transform.position=old;cc.enabled=enabled;Physics.SyncTransforms();EditorSceneManager.OpenScene(s.path);}File.WriteAllText(Path.GetFullPath(Path.Combine(Application.dataPath,"../../../Docs/검수/2026-11-08_C02_Refine/controller_walk.json")),JsonConvert.SerializeObject(results,Formatting.Indented));return results;}
}
